<?php
require_once '../../includes/verificar_admin.php';require_once '../../config/conexion.php';
$id=intval($_GET['id'] ?? 0);
$stmt=$conexion->prepare('SELECT * FROM clientes WHERE id_cliente=?');$stmt->execute([$id]);$cliente=$stmt->fetch();
if(!$cliente) { header('Location: listar.php');exit; }
$stmt=$conexion->prepare('SELECT COUNT(*) cantidad,COALESCE(SUM(CASE WHEN estado IN (\'Confirmado\',\'En preparación\',\'Enviado\',\'Entregado\') THEN total ELSE 0 END),0) importe FROM pedidos WHERE id_cliente=?');$stmt->execute([$id]);$metricas=$stmt->fetch();
$pagina=max(1,min(max(1,(int)ceil($metricas['cantidad']/25)),intval($_GET['pagina'] ?? 1)));
$stmt=$conexion->prepare('SELECT * FROM pedidos WHERE id_cliente=? ORDER BY id_pedido DESC LIMIT 25 OFFSET '.(($pagina-1)*25));$stmt->execute([$id]);$pedidos=$stmt->fetchAll();
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Historial del cliente · TechStore</title><link rel="stylesheet" href="../../css/admin.css"><link rel="stylesheet" href="../../css/admin-mejoras.css?v=20261013-menu"><link rel="stylesheet" href="../../css/experiencia.css?v=20261014"><script src="../../js/experiencia.js?v=20261014" defer></script>
<link rel="stylesheet" href="../../css/admin-experiencia.css?v=1"><script src="../../js/admin-experiencia.js?v=1" defer></script>
</head><body><?php render_admin_sidebar('clientes'); ?><div class="admin-main"><header class="admin-header"><h1>Historial del cliente</h1><a class="btn-action" href="listar.php">← Clientes</a></header><main class="admin-content"><section class="dashboard-cards"><article class="card-stat"><h3><?php echo e($cliente['nombre'].' '.$cliente['apellido']); ?></h3><p><?php echo e($cliente['correo']); ?></p><p><?php echo e($cliente['telefono']); ?></p></article><article class="card-stat"><h3>Pedidos registrados</h3><div class="number"><?php echo (int)$metricas['cantidad']; ?></div></article><article class="card-stat"><h3>Importe confirmado</h3><div class="number"><?php echo dinero($metricas['importe']); ?></div></article></section><table><thead><tr><th>Pedido</th><th>Fecha</th><th>Estado</th><th>Total</th><th>Detalle</th></tr></thead><tbody><?php foreach($pedidos as $pedido): ?><tr><td>#<?php echo (int)$pedido['id_pedido']; ?></td><td><?php echo e($pedido['fecha_pedido']); ?></td><td><?php echo e($pedido['estado']); ?></td><td><?php echo dinero($pedido['total']); ?></td><td><a class="btn-action" href="../pedidos/detalle.php?id=<?php echo (int)$pedido['id_pedido']; ?>">Ver pedido</a></td></tr><?php endforeach; ?><?php if(!$pedidos): ?><tr><td colspan="5">Este cliente aún no tiene pedidos.</td></tr><?php endif; ?></tbody></table><?php render_paginacion($pagina,max(1,(int)ceil($metricas['cantidad']/25)),(int)$metricas['cantidad']); ?></main></div></body></html>
